window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5024ef0dd423d845"]={"versions": [{"id": "FIG-5024ef0dd423d845", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses der Funktion <code>E2E_P22Forward</code>. Das Diagramm spezifiziert die Verhaltenslogik des E2E-Profils 22 (End-to-End Communication Protection) innerhalb der AUTOSAR-Basissoftware bzw. E2E-Bibliothek beim Weiterleiten (Forwarding) von Botschaften zwischen verschiedenen Kommunikationsbussen oder Software-Schichten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Funktion / Signatur: <code>E2E_P22Forward(Config, State, Data, Length, FowardStatus)</code></li>\n<li>Aktionen / Subaktivitäten:</li>\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Increment Counter</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li>Guard-Bedingungen: <code>[null input]</code>, <code>[input ok]</code>, <code>[wrong input]</code></li>\n<li>Kontrollknoten: Initialknoten (Start), drei Aktivitätsendknoten (<code>return</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start am Initialknoten beim Aufruf von <code>E2E_P22Forward(Config, State, Data, Length, FowardStatus)</code>.</li>\n<li>Ausführung der Aktion <code>Verify inputs of the protect function</code>.</li>\n<li>Verzweigung anhand der Übergangsbedingungen:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[null input]</code>: Direkter Übergang zum linken Aktivitätsendknoten mit Rückkehr (<code>return</code>).</li>\n<li><code>[wrong input]</code>: Direkter Übergang zum rechten Aktivitätsendknoten mit Rückkehr (<code>return</code>).</li>\n<li><code>[input ok]</code>: Fortsetzung des geschützten Weiterleitungsablaufs über den Hauptpfad.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Hauptpfad:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Increment Counter</code>: Der Sequenzzähler wird inkrementiert.</li>\n<li><code>Write Counter</code>: Der aktualisierte Zählerwert wird in die Nutzdaten/den PDU-Puffer geschrieben.</li>\n<li><code>Compute CRC</code>: Berechnung der Prüfsumme (CRC) über den Datenbereich gemäß Profil 22.</li>\n<li><code>Write CRC</code>: Schreiben der berechneten Prüfsumme in den dafür vorgesehenen PDU-Bereich.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Regulärer Abschluss am mittleren Aktivitätsendknoten mit Rückgabe (<code>return</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Bei Implementierung von <code>E2E_P22Forward</code> muss vor jeder Datenmanipulation eine vollständige Eingangsprüfung der übergebenen Zeiger und Parameter erfolgen.</li>\n<li>Ungültige Parameter (<code>null input</code> oder <code>wrong input</code>) führen zum sofortigen Funktionsabbruch ohne Aktualisierung von Counter oder CRC.</li>\n<li>Im Erfolgsfall (<code>input ok</code>) müssen die Modifikationen von Counter und CRC strikt sequenziell ausgeführt werden, da der inkrementierte Zählerwert in die CRC-Berechnung einfließt.</li>\n<li>Hinweis zur Funktionsbeschriftung: Der Parametername im Funktionskopf enthält den Tippfehler <code>FowardStatus</code> statt <code>ForwardStatus</code>, und die Subaktivität verweist auf <code>inputs of the protect function</code>, da die Forward-Funktion strukturell der Protect-Funktion ähnelt.</li>\n</ul>"}, {"id": "FIG-89d2b3d760268dde", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses der Funktion <code>E2E_P22Forward</code>. Das Diagramm spezifiziert die Verhaltenslogik des E2E-Profils 22 (End-to-End Communication Protection) innerhalb der AUTOSAR-Basissoftware bzw. E2E-Bibliothek beim Weiterleiten (Forwarding) von Botschaften zwischen verschiedenen Kommunikationsbussen oder Software-Schichten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Funktion / Signatur: <code>E2E_P22Forward(Config, State, Data, Length, FowardStatus)</code></li>\n<li>Aktionen / Subaktivitäten:</li>\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Increment Counter</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li>Guard-Bedingungen: <code>[null input]</code>, <code>[input ok]</code>, <code>[wrong input]</code></li>\n<li>Kontrollknoten: Initialknoten (Start), drei Aktivitätsendknoten (<code>return</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Start am Initialknoten beim Aufruf von <code>E2E_P22Forward(Config, State, Data, Length, FowardStatus)</code>.</li>\n<li>Ausführung der Aktion <code>Verify inputs of the protect function</code>.</li>\n<li>Verzweigung anhand der Übergangsbedingungen:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[null input]</code>: Direkter Übergang zum linken Aktivitätsendknoten mit Rückkehr (<code>return</code>).</li>\n<li><code>[wrong input]</code>: Direkter Übergang zum rechten Aktivitätsendknoten mit Rückkehr (<code>return</code>).</li>\n<li><code>[input ok]</code>: Fortsetzung des geschützten Weiterleitungsablaufs über den Hauptpfad.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Hauptpfad:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Increment Counter</code>: Der Sequenzzähler wird inkrementiert.</li>\n<li><code>Write Counter</code>: Der aktualisierte Zählerwert wird in die Nutzdaten/den PDU-Puffer geschrieben.</li>\n<li><code>Compute CRC</code>: Berechnung der Prüfsumme (CRC) über den Datenbereich gemäß Profil 22.</li>\n<li><code>Write CRC</code>: Schreiben der berechneten Prüfsumme in den dafür vorgesehenen PDU-Bereich.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Regulärer Abschluss am mittleren Aktivitätsendknoten mit Rückgabe (<code>return</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Bei Implementierung von <code>E2E_P22Forward</code> muss vor jeder Datenmanipulation eine vollständige Eingangsprüfung der übergebenen Zeiger und Parameter erfolgen.</li>\n<li>Ungültige Parameter (<code>null input</code> oder <code>wrong input</code>) führen zum sofortigen Funktionsabbruch ohne Aktualisierung von Counter oder CRC.</li>\n<li>Im Erfolgsfall (<code>input ok</code>) müssen die Modifikationen von Counter und CRC strikt sequenziell ausgeführt werden, da der inkrementierte Zählerwert in die CRC-Berechnung einfließt.</li>\n<li>Hinweis zur Funktionsbeschriftung: Der Parametername im Funktionskopf enthält den Tippfehler <code>FowardStatus</code> statt <code>ForwardStatus</code>, und die Subaktivität verweist auf <code>inputs of the protect function</code>, da die Forward-Funktion strukturell der Protect-Funktion ähnelt.</li>\n</ul>"}], "trans": [{"from": "FIG-5024ef0dd423d845", "to": "FIG-89d2b3d760268dde", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
